class Solution {
    public boolean canJump(int[] nums) {
        int farStep = 0;
        for (int i = 0; i < nums.length && i <= farStep; i++) {
            farStep = Math.max(farStep, nums[i] + i);
        }
        if (farStep >= nums.length-1)
            return true;
        return false;
    }
}
